window.FlashcardEngine=(()=>{const STORAGE_KEY_STATS="stone_flashcard_daily_stats_v1";const DEFAULT_KEY="apikey_21311d54ff438cd543d487365c0646a5ba09_4d0e27faf92f086612884a847f6b7536f90f5981a46bb19b0a65a6cf257375f5";let state={isOpen:false,mode:"study",targetCount:100,queue:[],currentIndex:0,currentWord:null,isEvaluating:false,isAnswered:false,lastResult:null,todayStats:{date:getTodayStr(),completed:0,correct:0,wrong:0,target:100}};function getTodayStr(){const d=new Date;return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`}function loadDailyStats(){try{const raw=typeof StoneStorage!=="undefined"?StoneStorage.getItem(STORAGE_KEY_STATS):localStorage.getItem(STORAGE_KEY_STATS);if(raw){const parsed=JSON.parse(raw);if(parsed.date===getTodayStr()){state.todayStats=parsed;return}}}catch(e){}state.todayStats={date:getTodayStr(),completed:0,correct:0,wrong:0,target:state.targetCount};saveDailyStats()}function saveDailyStats(){try{const str=JSON.stringify(state.todayStats);if(typeof StoneStorage!=="undefined")StoneStorage.setItem(STORAGE_KEY_STATS,str);localStorage.setItem(STORAGE_KEY_STATS,str)}catch(e){}}function getStandardDefinition(word){if(!word)return"";const clean=word.toLowerCase().trim();if(typeof chineseDict!=="undefined"&&chineseDict[clean]){return chineseDict[clean]}if(typeof fullChineseDict!=="undefined"&&fullChineseDict[clean]){return fullChineseDict[clean]}if(typeof extraDefinitions!=="undefined"&&extraDefinitions[clean]){const ext=extraDefinitions[clean];return typeof ext==="string"?ext:ext.zh||ext.definition||""}return""}function verifyLocally(word,input,standardDef){if(!input||!standardDef)return null;const cleanInput=input.trim().toLowerCase();const cleanDef=standardDef.toLowerCase();const defWithoutPos=cleanDef.replace(/[a-z]+\./g,"").trim();const segments=defWithoutPos.split(/[；;,，/、\s\(\)（）]+/).map(s=>s.trim()).filter(s=>s.length>0);for(const seg of segments){if(cleanInput===seg||cleanInput.length>=2&&seg.includes(cleanInput)||seg.length>=2&&cleanInput.includes(seg)){return{correct:true,confidence:1,source:"local_fast",reason:`精准命中词条释义: “${seg}”`}}}return null}async function verifyWithJev(word,input,standardDef){const key=typeof appSettings!=="undefined"&&appSettings.typesafeKey?appSettings.typesafeKey:DEFAULT_KEY;const url="https://api.typesafe.ai/v1/systemone";const payload={state:{word:word,standard_definition:standardDef||"无本地释义，请按目标英语单词本身通用释义判定",user_input:input},model:"jev-latest",questions:{is_correct:{type:"noul",instructions:"判断用户的解释（无论是中文表达还是英文解释）是否准确表达或切中了目标单词的核心含义。",criteria:{true:"用户解释正确、近义或切中了单词的核心考点/常用含义",false:"解释严重错误、张冠李戴、毫无关联或完全无意义乱填"}}}};const startTime=performance.now();const resp=await fetch(url,{method:"POST",headers:{Authorization:`Bearer ${key}`,"Content-Type":"application/json"},body:JSON.stringify(payload)});if(!resp.ok){throw new Error(`Jev 接口响应异常: ${resp.status}`)}const data=await resp.json();const elapsed=Math.round(performance.now()-startTime);const noulVal=data.answers?.is_correct?.noul??0;const isCorrect=noulVal>=.6;return{correct:isCorrect,confidence:noulVal,elapsedMs:elapsed,source:"jev_model",reason:isCorrect?`Jev 模型判卷通过 (置信度: ${(noulVal*100).toFixed(0)}%, 耗时: ${elapsed}ms)`:`Jev 模型判定未切中核心考点 (置信度: ${(noulVal*100).toFixed(0)}%, 耗时: ${elapsed}ms)`}}function initQueue(){let list=[];if(state.mode==="review"){if(typeof getMarkedWords==="function"){list=[...getMarkedWords()]}if(list.length<state.targetCount&&typeof getActiveWordList==="function"){const full=getActiveWordList();for(const w of full){if(!list.includes(w))list.push(w);if(list.length>=state.targetCount)break}}}else{if(typeof getActiveWordList==="function"){list=[...getActiveWordList()]}}if(list.length===0&&typeof words!=="undefined"){list=[...words]}state.queue=list.slice(0,state.targetCount);state.currentIndex=0;state.currentWord=state.queue[0]||null;state.isAnswered=false;state.lastResult=null}function open(mode="study",target=100){state.isOpen=true;state.mode=mode;state.targetCount=target;loadDailyStats();initQueue();const modal=document.getElementById("flashcardModal");if(modal){modal.style.display="flex";requestAnimationFrame(()=>modal.classList.add("open"));renderCard()}}function close(){state.isOpen=false;const modal=document.getElementById("flashcardModal");if(modal){modal.classList.remove("open");setTimeout(()=>{modal.style.display="none"},200)}if(typeof updateBadges==="function")updateBadges()}function renderCard(){if(!state.isOpen)return;const word=state.queue[state.currentIndex];state.currentWord=word;state.isAnswered=false;state.lastResult=null;const modal=document.getElementById("flashcardModal");if(!modal)return;if(!word||state.currentIndex>=state.queue.length){renderFinishedState();return}const standardDef=getStandardDefinition(word);const markCount=typeof getMarkCount==="function"?getMarkCount(word):0;const progressPercent=Math.min(100,Math.round(state.todayStats.completed/state.todayStats.target*100));modal.innerHTML=`\n      <div class="flashcard-container">\n        \x3c!-- 顶部 HUD 状态栏 --\x3e\n        <div class="flashcard-hud">\n          <div class="flashcard-hud-left">\n            <button class="btn btn-secondary btn-xs" onclick="FlashcardEngine.close()" title="退出研习 (Esc)">✕ 退出</button>\n            <div class="flashcard-mode-pill ${state.mode==="study"?"study-pill":"review-pill"}" onclick="FlashcardEngine.toggleMode()">\n              <span>${state.mode==="study"?"📖 新词研习":"🔄 重点复习"}</span>\n              <span style="font-size:10px;opacity:0.75;">(点击切换)</span>\n            </div>\n          </div>\n          <div class="flashcard-hud-right">\n            <span class="flashcard-stat-chip">今日达成: <strong>${state.todayStats.completed}</strong> / ${state.todayStats.target}</span>\n            <span class="flashcard-stat-chip">本次进度: <strong>${state.currentIndex+1}</strong> / ${state.queue.length}</span>\n          </div>\n        </div>\n\n        \x3c!-- 进度条 --\x3e\n        <div class="flashcard-progress-bar">\n          <div class="flashcard-progress-fill" style="width: ${progressPercent}%;"></div>\n        </div>\n\n        \x3c!-- 折纸主卡片 --\x3e\n        <div class="flashcard-card-box" id="flashcardBox">\n          \x3c!-- 卡片正面头部 --\x3e\n          <div class="flashcard-word-row">\n            <h1 class="flashcard-word" id="fcWordTitle" onclick="FlashcardEngine.speakCurrent()">${escapeHtml(word)}</h1>\n            <button class="flashcard-speaker-btn" onclick="FlashcardEngine.speakCurrent()" title="发音 (Space)">🔊</button>\n            ${markCount>0?`<span class="flashcard-mark-tag">★ Marked ×${markCount}</span>`:""}\n          </div>\n\n          <div class="flashcard-hint-row" id="fcHintRow">\n            <span class="flashcard-hint-sub">💡 请在下方输入该词的中文或英文释义，回车提交：</span>\n          </div>\n\n          \x3c!-- 输入区域 --\x3e\n          <div class="flashcard-input-wrap" id="fcInputWrap">\n            <input type="text" id="fcInput" class="flashcard-input" placeholder="输入中文或英文释义 (例如: 放弃 / to give up)..." autocomplete="off" />\n            <button class="btn btn-primary flashcard-submit-btn" id="fcSubmitBtn" onclick="FlashcardEngine.submitAnswer()">判卷 (Enter)</button>\n          </div>\n\n          \x3c!-- 极速判定中状态条 (默认隐藏) --\x3e\n          <div class="flashcard-evaluating-row" id="fcEvaluating" style="display: none;">\n            <div class="flashcard-spinner"></div>\n            <span>⚡ TypeSafe Jev 正在极速判卷中...</span>\n          </div>\n\n          \x3c!-- 判定结果展示区 (默认隐藏) --\x3e\n          <div class="flashcard-result-panel" id="fcResultPanel" style="display: none;">\n            \x3c!-- 动态注入结果 --\x3e\n          </div>\n        </div>\n\n        \x3c!-- 底部快捷键提示 --\x3e\n        <div class="flashcard-footer-tip">\n          <span>快捷键: <strong>Enter</strong> 提交/下一词 · <strong>Space</strong> 发音 · <strong>Esc</strong> 退出</span>\n        </div>\n      </div>\n    `;setTimeout(()=>{const input=document.getElementById("fcInput");if(input){input.focus();setupInputListener(input)}speakCurrent()},50)}function setupInputListener(input){let isComposing=false;input.addEventListener("compositionstart",()=>{isComposing=true});input.addEventListener("compositionend",()=>{isComposing=false});input.addEventListener("keydown",e=>{if(isComposing)return;if(e.key==="Enter"){e.preventDefault();if(state.isAnswered){nextWord()}else{submitAnswer()}}})}function speakCurrent(){if(!state.currentWord)return;if(typeof speakWord==="function"){speakWord(state.currentWord)}}async function submitAnswer(){if(state.isEvaluating||state.isAnswered||!state.currentWord)return;const inputEl=document.getElementById("fcInput");if(!inputEl)return;const val=inputEl.value.trim();if(!val){if(typeof showToast==="function")showToast("⚠️ 请先输入你理解的释义");inputEl.focus();return}state.isEvaluating=true;const submitBtn=document.getElementById("fcSubmitBtn");const evalRow=document.getElementById("fcEvaluating");if(submitBtn)submitBtn.disabled=true;if(evalRow)evalRow.style.display="flex";const word=state.currentWord;const standardDef=getStandardDefinition(word);let result=null;try{const localRes=verifyLocally(word,val,standardDef);if(localRes){result=localRes}else{result=await verifyWithJev(word,val,standardDef)}}catch(err){console.warn("Jev 判定异常，执行本地柔性比对:",err);const fallbackPass=val.length>=2&&standardDef.includes(val);result={correct:fallbackPass,confidence:.5,source:"fallback",reason:fallbackPass?"本地模糊匹配通过":"未击中考纲释义"}}finally{state.isEvaluating=false;if(evalRow)evalRow.style.display="none";if(submitBtn)submitBtn.disabled=false}applyEvaluationResult(result,val,standardDef)}function applyEvaluationResult(result,userInput,standardDef){state.isAnswered=true;state.lastResult=result;state.todayStats.completed+=1;if(result.correct){state.todayStats.correct+=1;if(typeof soundSuccess==="function")soundSuccess();if(state.mode==="review"&&typeof reduceMark==="function"){reduceMark(state.currentWord)}}else{state.todayStats.wrong+=1;if(typeof soundFailure==="function")soundFailure();if(typeof addMark==="function"){addMark(state.currentWord)}}saveDailyStats();const cardBox=document.getElementById("flashcardBox");const resultPanel=document.getElementById("fcResultPanel");const inputWrap=document.getElementById("fcInputWrap");const submitBtn=document.getElementById("fcSubmitBtn");if(cardBox){cardBox.classList.remove("is-correct","is-wrong");cardBox.classList.add(result.correct?"is-correct":"is-wrong")}if(resultPanel){resultPanel.style.display="block";resultPanel.innerHTML=`\n        <div class="flashcard-badge-row">\n          <span class="flashcard-verdict-badge ${result.correct?"badge-correct":"badge-wrong"}">\n            ${result.correct?"✅ 判定正确！":"❌ 释义有偏差"}\n          </span>\n          <span class="flashcard-confidence-info">${escapeHtml(result.reason)}</span>\n        </div>\n\n        <div class="flashcard-def-comparison">\n          <div class="flashcard-compare-item">\n            <span class="compare-label">你的释义:</span>\n            <span class="compare-content user-input-text">${escapeHtml(userInput)}</span>\n          </div>\n          <div class="flashcard-compare-item">\n            <span class="compare-label">标准权威释义:</span>\n            <span class="compare-content std-def-text">${escapeHtml(standardDef||"暂无详细中文释义")}</span>\n          </div>\n        </div>\n\n        <div class="flashcard-action-bar">\n          <button class="btn btn-primary flashcard-next-btn" onclick="FlashcardEngine.nextWord()">\n            ${state.currentIndex+1<state.queue.length?"下一个 (Enter)":"查看研习战报 (Enter)"} ➔\n          </button>\n          ${!result.correct?`<button class="btn btn-secondary" onclick="FlashcardEngine.retryCurrent()">再试一次</button>`:""}\n        </div>\n      `}if(inputWrap){inputWrap.style.display="none"}}function retryCurrent(){state.isAnswered=false;state.lastResult=null;const cardBox=document.getElementById("flashcardBox");const resultPanel=document.getElementById("fcResultPanel");const inputWrap=document.getElementById("fcInputWrap");const inputEl=document.getElementById("fcInput");if(cardBox)cardBox.classList.remove("is-correct","is-wrong");if(resultPanel)resultPanel.style.display="none";if(inputWrap)inputWrap.style.display="flex";if(inputEl){inputEl.value="";inputEl.focus()}}function nextWord(){state.currentIndex+=1;renderCard()}function toggleMode(){const nextMode=state.mode==="study"?"review":"study";open(nextMode,state.targetCount)}function renderFinishedState(){const modal=document.getElementById("flashcardModal");if(!modal)return;const accuracy=state.todayStats.completed>0?Math.round(state.todayStats.correct/state.todayStats.completed*100):0;modal.innerHTML=`\n      <div class="flashcard-container">\n        <div class="flashcard-card-box finished-box">\n          <div class="finished-trophy">🏆</div>\n          <h2 style="font-size:24px; font-weight:800; margin: 12px 0 6px;">研习圆满达成！</h2>\n          <p style="color:var(--text-secondary); font-size:14px; margin-bottom: 20px;">\n            今日已完成 <strong>${state.todayStats.completed}</strong> 个单词的深度研习与极速智能判卷。\n          </p>\n\n          <div class="finished-stats-grid">\n            <div class="finished-stat-card">\n              <span class="stat-num" style="color:var(--brand-success);">${state.todayStats.correct}</span>\n              <span class="stat-lbl">答对词数</span>\n            </div>\n            <div class="finished-stat-card">\n              <span class="stat-num" style="color:var(--brand-danger);">${state.todayStats.wrong}</span>\n              <span class="stat-lbl">强化记错</span>\n            </div>\n            <div class="finished-stat-card">\n              <span class="stat-num" style="color:var(--brand-primary);">${accuracy}%</span>\n              <span class="stat-lbl">准确率</span>\n            </div>\n          </div>\n\n          <div style="display:flex; gap:12px; justify-content:center; margin-top:24px; flex-wrap:wrap;">\n            <button class="btn btn-primary" onclick="FlashcardEngine.open('${state.mode}', ${state.targetCount})">再来一组 (100词)</button>\n            <button class="btn btn-secondary" onclick="FlashcardEngine.close()">返回词库</button>\n          </div>\n        </div>\n      </div>\n    `;if(typeof soundSuccess==="function")soundSuccess()}return{open:open,close:close,submitAnswer:submitAnswer,nextWord:nextWord,retryCurrent:retryCurrent,toggleMode:toggleMode,speakCurrent:speakCurrent}})();